#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <openssl/evp.h>

static double now() {
    struct timespec ts;
    clock_gettime(CLOCK_MONOTONIC, &ts);
    return ts.tv_sec + ts.tv_nsec * 1e-9;
}

int main() {
    size_t n = 40000ULL * 1024;
    unsigned char *pt = malloc(n);
    unsigned char *ct = malloc(n + 16);
    unsigned char key[32], nonce[12], aad[32];
    memset(pt, 1, n);
    memset(key, 2, 32);
    memset(nonce, 3, 12);
    memset(aad, 4, 32);

    EVP_CIPHER_CTX *ctx = EVP_CIPHER_CTX_new();
    const EVP_CIPHER *cipher = EVP_chacha20_poly1305();

    /* warmup */
    for (int i = 0; i < 2; i++) {
        int len = 0, len2 = 0;
        EVP_EncryptInit_ex(ctx, cipher, NULL, NULL, NULL);
        EVP_CIPHER_CTX_ctrl(ctx, EVP_CTRL_AEAD_SET_IVLEN, 12, NULL);
        EVP_EncryptInit_ex(ctx, NULL, NULL, key, nonce);
        EVP_EncryptUpdate(ctx, NULL, &len, aad, 32);
        EVP_EncryptUpdate(ctx, ct, &len, pt, (int)n);
        EVP_EncryptFinal_ex(ctx, ct + len, &len2);
        EVP_CIPHER_CTX_ctrl(ctx, EVP_CTRL_AEAD_GET_TAG, 16, ct + len);
    }
    double t0 = now();
    int reps = 5;
    for (int i = 0; i < reps; i++) {
        int len = 0, len2 = 0;
        EVP_EncryptInit_ex(ctx, cipher, NULL, NULL, NULL);
        EVP_CIPHER_CTX_ctrl(ctx, EVP_CTRL_AEAD_SET_IVLEN, 12, NULL);
        EVP_EncryptInit_ex(ctx, NULL, NULL, key, nonce);
        EVP_EncryptUpdate(ctx, NULL, &len, aad, 32);
        EVP_EncryptUpdate(ctx, ct, &len, pt, (int)n);
        EVP_EncryptFinal_ex(ctx, ct + len, &len2);
        EVP_CIPHER_CTX_ctrl(ctx, EVP_CTRL_AEAD_GET_TAG, 16, ct + len);
    }
    double dt = now() - t0;
    printf("EVP: %.3f s/op  %.2f GB/s  ct0=%02x\n", dt/reps, (reps * (double)n) / dt / 1e9, ct[0]);

    /* reuse ctx without re-setting cipher each time */
    t0 = now();
    for (int i = 0; i < reps; i++) {
        int len = 0, len2 = 0;
        EVP_EncryptInit_ex(ctx, NULL, NULL, key, nonce);
        EVP_EncryptUpdate(ctx, NULL, &len, aad, 32);
        EVP_EncryptUpdate(ctx, ct, &len, pt, (int)n);
        EVP_EncryptFinal_ex(ctx, ct + len, &len2);
        EVP_CIPHER_CTX_ctrl(ctx, EVP_CTRL_AEAD_GET_TAG, 16, ct + len);
    }
    dt = now() - t0;
    printf("EVP reuse: %.3f s/op  %.2f GB/s\n", dt/reps, (reps * (double)n) / dt / 1e9);
    return 0;
}
EOF
