/* OpenSSL internal */
void ChaCha20_ctr32(unsigned char *out, const unsigned char *inp,
                    size_t len, const unsigned int key[8],
                    const unsigned int counter[4]);

static double now() {
    struct timespec ts; clock_gettime(CLOCK_MONOTONIC, &ts);
    return ts.tv_sec + ts.tv_nsec*1e-9;
}

int main() {
    size_t n = 40000ULL * 1024;
    unsigned char *pt = malloc(n);
    unsigned char *ct = malloc(n);
    memset(pt, 1, n);
    unsigned int key[8] = {0};
    unsigned int counter[4] = {0, 1, 2, 3};
    /* warmup */
    ChaCha20_ctr32(ct, pt, n, key, counter);
    double t0 = now();
    int reps = 5;
    for (int i = 0; i < reps; i++)
        ChaCha20_ctr32(ct, pt, n, key, counter);
    double dt = now() - t0;
    printf("ChaCha20_ctr32: %.4f s/op  %.2f GB/s  ct0=%02x\n", dt/reps, reps*(double)n/dt/1e9, ct[0]);

    /* keystream only (inp NULL?) */
    t0 = now();
    for (int i = 0; i < reps; i++)
        ChaCha20_ctr32(ct, NULL, n, key, counter);
    dt = now() - t0;
    printf("ChaCha20_ctr32 NULL inp: %.4f s/op  %.2f GB/s\n", dt/reps, reps*(double)n/dt/1e9);

    /* smaller chunks to see */
    return 0;
}
