{"command":"cat > bench_low.c << 'EOF'
#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <stdint.h>

void ChaCha20_ctr32(unsigned char *out, const unsigned char *inp,
                    size_t len, const unsigned int key[8],
                    const unsigned int counter[4]);

size_t Poly1305_ctx_size(void);
void Poly1305_Init(void *ctx, const unsigned char key[32]);
void Poly1305_Update(void *ctx, const unsigned char *inp, size_t len);
void Poly1305_Final(void *ctx, unsigned char mac[16]);

static double now() {
    struct timespec ts; clock_gettime(CLOCK_MONOTONIC, &ts);
    return ts.tv_sec + ts.tv_nsec*1e-9;
}

int main() {
    printf("poly ctx size %zu\n", Poly1305_ctx_size());
    size_t n = 40000ULL * 1024;
    unsigned char *pt = malloc(n);
    unsigned char *ct = malloc(n + 64);
    memset(pt, 1, n);
    unsigned int key[8];
    for (int i = 0; i < 8; i++) key[i] = i*17+3;
    unsigned int counter[4] = {0, 0x01020304, 0x05060708, 0x090a0b0c};

    ChaCha20_ctr32(ct, pt, n, key, counter);
    double t0 = now();
    int reps = 6;
    for (int i = 0; i < reps; i++)
        ChaCha20_ctr32(ct, pt, n, key, counter);
    double dt = now() - t0;
    printf("ChaCha20_ctr32: %.4f s/op  %.2f GB/s  ct0=%02x %02x\n", dt/reps, reps*(double)n/dt/1e9, ct[0], ct[1]);

    /* poly1305 over same buffer */
    unsigned char pkey[32]; memset(pkey, 7, 32);
    unsigned char ctx[256];
    unsigned char mac[16];
    Poly1305_Init(ctx, pkey);
    Poly1305_Update(ctx, ct, n);
    Poly1305_Final(ctx, mac);
    t0 = now();
    for (int i = 0; i < reps; i++) {
        Poly1305_Init(ctx, pkey);
        Poly1305_Update(ctx, ct, n);
        Poly1305_Final(ctx, mac);
    }
    dt = now() - t0;
    printf("Poly1305: %.4f s/op  %.2f GB/s  mac0=%02x\n", dt/reps, reps*(double)n/dt/1e9, mac[0]);

    /* combined sequential */
    t0 = now();
    for (int i = 0; i < reps; i++) {
        ChaCha20_ctr32(ct, pt, n, key, counter);
        Poly1305_Init(ctx, pkey);
        Poly1305_Update(ctx, ct, n);
        Poly1305_Final(ctx, mac);
    }
    dt = now() - t0;
    printf("sequential both: %.4f s/op  %.2f GB/s\n", dt/reps, reps*(double)n/dt/1e9);
    return 0;
}
EOF
cc -O3 -o bench_low bench_low.c -L/usr/local/lib -lcrypto && ./bench_low"}

{"command":"cat > bench_par.c << 'EOF'
#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <pthread.h>
#include <stdint.h>

void ChaCha20_ctr32(unsigned char *out, const unsigned char *inp,
                    size_t len, const unsigned int key[8],
                    const unsigned int counter[4]);

typedef struct {
    unsigned char *out, *in;
    size_t len;
    unsigned int key[8];
    unsigned int counter[4];
    pthread_barrier_t *bar;
    int stop;
    int reps;
} job;

void *worker(void *arg) {
    job *j = arg;
    for (;;) {
        pthread_barrier_wait(j->bar);
        if (j->stop) { pthread_barrier_wait(j->bar); return NULL; }
        for (int r = 0; r < j->reps; r++)
            ChaCha20_ctr32(j->out, j->in, j->len, j->key, j->counter);
        pthread_barrier_wait(j->bar);
    }
}

static double now() {
    struct timespec ts; clock_gettime(CLOCK_MONOTONIC, &ts);
    return ts.tv_sec + ts.tv_nsec*1e-9;
}

int main() {
    size_t n = 40000ULL * 1024;
    int reps = 4;
    for (int nt = 1; nt <= 6; nt++) {
        size_t chunk = (n / nt) & ~63ULL;
        size_t total = chunk * nt;
        unsigned char *pt = malloc(total);
        unsigned char *ct = malloc(total);
        memset(pt, 1, total);
        pthread_barrier_t bar;
        pthread_barrier_init(&bar, NULL, nt+1);
        job *jobs = calloc(nt, sizeof(job));
        pthread_t *ths = calloc(nt, sizeof(pthread_t));
        for (int i = 0; i < nt; i++) {
            jobs[i].out = ct + i*chunk;
            jobs[i].in = pt + i*chunk;
            jobs[i].len = chunk;
            jobs[i].counter[0] = (unsigned int)((i*chunk)/64);
            jobs[i].bar = &bar;
            jobs[i].reps = reps;
            pthread_create(&ths[i], NULL, worker, &jobs[i]);
        }
        /* warmup */
        pthread_barrier_wait(&bar);
        pthread_barrier_wait(&bar);
        pthread_barrier_wait(&bar);
        double t0 = now();
        pthread_barrier_wait(&bar);
        double dt = now() - t0;
        printf("threads=%d  %.4f s/op  %.2f GB/s\n", nt, dt/reps, reps*(double)total/dt/1e9);
        for (int i = 0; i < nt; i++) jobs[i].stop = 1;
        pthread_barrier_wait(&bar);
        pthread_barrier_wait(&bar);
        for (int i = 0; i < nt; i++) pthread_join(ths[i], NULL);
        free(pt); free(ct); free(jobs); free(ths);
        pthread_barrier_destroy(&bar);
    }
    return 0;
}
EOF
cc -O3 -o bench_par bench_par.c -L/usr/local/lib -lcrypto -lpthread && ./bench_par"}

