{"command":"cat > chacha_aead.c << 'EOF'
#include <stdint.h>
#include <stddef.h>
#include <string.h>
#include <stdlib.h>
#include <pthread.h>

void ChaCha20_ctr32(unsigned char *out, const unsigned char *inp,
                    size_t len, const unsigned int key[8],
                    const unsigned int counter[4]);
void Poly1305_Init(void *ctx, const unsigned char key[32]);
void Poly1305_Update(void *ctx, const unsigned char *inp, size_t len);
void Poly1305_Final(void *ctx, unsigned char mac[16]);

typedef struct {
    unsigned char *out;
    const unsigned char *in;
    size_t len;
    unsigned int key[8];
    unsigned int counter[4];
} chunk_job;

static void *chunk_worker(void *arg) {
    chunk_job *j = (chunk_job *)arg;
    ChaCha20_ctr32(j->out, j->in, j->len, j->key, j->counter);
    return NULL;
}

/*
 * Encrypt pt in parallel (nt threads) and compute Poly1305 tag.
 * ct must have n bytes; tag must have 16 bytes.
 * aad may be NULL if aad_len == 0.
 */
int chacha20_poly1305_encrypt(const unsigned char key[32],
                              const unsigned char nonce[12],
                              const unsigned char *pt, size_t n,
                              const unsigned char *aad, size_t aad_len,
                              unsigned char *ct, unsigned char tag[16],
                              int nt) {
    unsigned int kw[8];
    memcpy(kw, key, 32);
    unsigned int nw[3];
    memcpy(nw, nonce, 12);

    unsigned char zeros[64] = {0};
    unsigned char polykey[64];
    unsigned int c0[4] = {0, nw[0], nw[1], nw[2]};
    ChaCha20_ctr32(polykey, zeros, 64, kw, c0);

    if (nt < 1) nt = 1;
    if ((size_t)nt > n / 64) nt = (int)(n / 64);
    if (nt < 1) nt = 1;

    if (nt == 1 || n < 4096) {
        unsigned int c1[4] = {1, nw[0], nw[1], nw[2]};
        ChaCha20_ctr32(ct, pt, n, kw, c1);
    } else {
        size_t base = (n / nt) & ~(size_t)63;
        chunk_job jobs[16];
        pthread_t ths[16];
        if (nt > 16) nt = 16;
        size_t off = 0;
        int launched = 0;
        for (int i = 0; i < nt; i++) {
            size_t ln = (i == nt - 1) ? (n - off) : base;
            jobs[i].out = ct + off;
            jobs[i].in = pt + off;
            jobs[i].len = ln;
            memcpy(jobs[i].key, kw, 32);
            unsigned int ctr = 1u + (unsigned int)(off / 64);
            jobs[i].counter[0] = ctr;
            jobs[i].counter[1] = nw[0];
            jobs[i].counter[2] = nw[1];
            jobs[i].counter[3] = nw[2];
            if (i < nt - 1) {
                pthread_create(&ths[i], NULL, chunk_worker, &jobs[i]);
                launched++;
            } else {
                chunk_worker(&jobs[i]);
            }
            off += ln;
        }
        for (int i = 0; i < launched; i++) pthread_join(ths[i], NULL);
    }

    /* Poly1305 over aad || pad || ct || pad || le64(aad_len) || le64(n) */
    unsigned char ctx[256];
