    uint64_t low0 = w0;
    uint64_t low1 = w1;
    uint64_t low2 = w2 & 3ull; /* bits 128..129 */

    /* high130 = bits 130..259 = (w2 >> 2) | (w3 << 62)  for low 64 of high? 
       bits 130..193 = w2[2..63] | w3[0..1]  -> 64 bits
       bits 194..257 = w3[2..63] | w4[0..1]
       bits 258..259 = w4[2..3]
    */
    uint64_t hi0 = (w2 >> 2) | (w3 << 62);
    uint64_t hi1 = (w3 >> 2) | (w4 << 62);
    uint64_t hi2 = (w4 >> 2) & 3ull;

    /* high * 5 = high * 4 + high */
    uint64_t t0, t1, t2, c;
    /* *4 */
    t0 = hi0 << 2;
    t1 = (hi1 << 2) | (hi0 >> 62);
    t2 = (hi2 << 2) | (hi1 >> 62);
    /* + high */
    c = 0;
    uint64_t s0 = t0 + hi0; c = s0 < t0;
    uint64_t s1 = t1 + hi1 + c; c = (s1 < t1) || (c && s1 == t1);
    /* careful carry */
    /* redo with __uint128 */
    unsigned __int128 s;
    s = (unsigned __int128)t0 + hi0;
    s0 = (uint64_t)s;
    s = (unsigned __int128)t1 + hi1 + (uint64_t)(s >> 64);
    s1 = (uint64_t)s;
    s = (unsigned __int128)t2 + hi2 + (uint64_t)(s >> 64);
    uint64_t s2 = (uint64_t)s; /* fits in ~3 bits + carry, < 16 */

    /* add to low */
    s = (unsigned __int128)low0 + s0;
    uint64_t r0 = (uint64_t)s;
    s = (unsigned __int128)low1 + s1 + (uint64_t)(s >> 64);
    uint64_t r1 = (uint64_t)s;
    s = (unsigned __int128)low2 + s2 + (uint64_t)(s >> 64);
    uint64_t r2 = (uint64_t)s; /* may be > 3 */

    /* r2 may be up to ~20. Fold r2>>2 * 5 into low. */
    while (r2 >= 4) {
        uint64_t extra = (r2 >> 2) * 5; /* small */
        r2 &= 3ull;
        s = (unsigned __int128)r0 + extra;
        r0 = (uint64_t)s;
        s = (unsigned __int128)r1 + (uint64_t)(s >> 64);
        r1 = (uint64_t)s;
        r2 += (uint64_t)(s >> 64);
    }
    /* if value >= P, subtract P. P = 2^130-5. value >= P iff r2==3 && (r1==~0 && r0>=~4) i.e. low128 >= 2^128-5, or r2>3 (already folded). */
    if (r2 == 3) {
        /* compare low128 with 2^128-5 = {~4, ~0} */
        if (r1 > ~0ull - 0 || (r1 == ~0ull && r0 >= (~4ull))) {
            /* subtract 2^130-5 == add 5 and clear top, since value = 2^130 + (low- (2^128... wait)
               value - (2^130 - 5) = value - 2^130 + 5 = (r2_cleared) + 5
               since r2==3 means bits 128-129 are both set, which IS 2^128+2^129 = 3*2^128, and 2^130 = 4*2^128.
               value - 2^130 + 5 = (value + 5) - 2^130.
               value + 5 will carry into bit 130 exactly when low128+5 >= 2^128, which is true because
               low128 >= 2^128-5 so low128+5 >= 2^128. The carry clears bit 130 (r2 becomes 0 after subtracting 4*2^128).
            */
            s = (unsigned __int128)r0 + 5;
            r0 = (uint64_t)s;
            s = (unsigned __int128)r1 + (uint64_t)(s >> 64);
            r1 = (uint64_t)s;
            r2 = 0; /* the +1 carry into r2 makes r2==4, minus 4 (2^130) = 0. 
                       If r1 didn't overflow to produce carry, we were wrong. 
                       low128 >= 2^128-5 guarantees carry out of low128 when adding 5. */
            (void)s;
        }
    }
    u130 out;
    out.l0 = r0;
    out.l1 = r1;
    out.h2 = r2;
    return out;
}

static u130 mul130(u130 a, u130 b) {
    /* schoolbook 3-limb but limbs are 64,64,2. Use 64-bit limbs of a (a0,a1,a2) * b. */
    uint64_t a0 = a.l0, a1 = a.l1, a2 = a.h2;
    uint64_t b0 = b.l0, b1 = b.l1, b2 = b.h2;
    unsigned __int128 p;
    uint64_t w0, w1, w2, w3, w4;
    uint64_t c;

    /* w = a0*b0 */
    p = (unsigned __int128)a0 * b0;
    w0 = (uint64_t)p; w1 = (uint64_t)(p >> 64);
    /* + a0*b1 */
    p = (unsigned __int128)a0 * b1 + w1;
    w1 = (uint64_t)p; w2 = (uint64_t)(p >> 64);
    /* + a0*b2 */
    p = (unsigned __int128)a0 * b2 + w2;
    w2 = (uint64_t)p; w3 = (uint64_t)(p >> 64);
    w4 = 0;

    /* + a1*b0 */
    p = (unsigned __int128)a1 * b0 + w1;
    w1 = (uint64_t)p; c = (uint64_t)(p >> 64);
    p = (unsigned __int128)w2 + c;
    w2 = (uint64_t)p; c = (uint64_t)(p >> 64);
    p = (unsigned __int128)w3 + c;
    w3 = (uint64_t)p; w4 += (uint64_t)(p >> 64);

    /* + a1*b1 */
    p = (unsigned __int128)a1 * b1 + w2;
    w2 = (uint64_t)p; c = (uint64_t)(p >> 64);
    p = (unsigned __int128)w3 + c;
    w3 = (uint64_t)p; c = (uint64_t)(p >> 64);
    w4 += c;

    /* + a1*b2 */
    p = (unsigned __int128)a1 * b2 + w3;
    w3 = (uint64_t)p; w4 += (uint64_t)(p >> 64);

    /* + a2*b0 */
    p = (unsigned __int128)a2 * b0 + w2;
    w2 = (uint64_t)p; c = (uint64_t)(p >> 64);
    p = (unsigned __int128)w3 + c;
    w3 = (uint64_t)p; c = (uint64_t)(p >> 64);
    w4 += c;

    /* + a2*b1 */
    p = (unsigned __int128)a2 * b1 + w3;
    w3 = (uint64_t)p; w4 += (uint64_t)(p >> 64);

    /* + a2*b2 */
    p = (unsigned __int128)a2 * b2 + w4;
    w4 = (uint64_t)p; /* product of 2-bit values fits, no further */

    return reduce_260(w0, w1, w2, w3, w4);
}

static u130 add130(u130 a, u130 b) {
    unsigned __int128 s;
    s = (unsigned __int128)a.l0 + b.l0;
    uint64_t r0 = (uint64_t)s;
    s = (unsigned __int128)a.l1 + b.l1 + (uint64_t)(s >> 64);
    uint64_t r1 = (uint64_t)s;
    uint64_t r2 = a.h2 + b.h2 + (uint64_t)(s >> 64);
    /* r2 <= 6. fold */
    if (r2 >= 4) {
        uint64_t extra = (r2 >> 2) * 5;
        r2 &= 3ull;
        s = (unsigned __int128)r0 + extra;
        r0 = (uint64_t)s;
        s = (unsigned __int128)r1 + (uint64_t)(s >> 64);
        r1 = (uint64_t)s;
        r2 += (uint64_t)(s >> 64);
    }
    if (r2 == 3 && r1 == ~0ull && r0 >= (~4ull)) {
        s = (unsigned __int128)r0 + 5;
        r0 = (uint64_t)s;
        s = (unsigned __int128)r1 + (uint64_t)(s >> 64);
        r1 = (uint64_t)s;
        r2 = 0;
    }
    u130 o; o.l0 = r0; o.l1 = r1; o.h2 = r2;
    return o;
}

static u130 pow130(u130 base, uint64_t exp) {
    u130 result; result.l0 = 1; result.l1 = 0; result.h2 = 0;
    while (exp) {
        if (exp & 1) result = mul130(result, base);
        exp >>= 1;
        if (exp) base = mul130(base, base);
    }
    return result;
}

static u130 load_h(const unsigned char *ctx) {
    uint32_t flag = 0;
    memcpy(&flag, ctx + 0x14, 4);
    u130 h; h.l0 = 0; h.l1 = 0; h.h2 = 0;
    if (flag) {
        uint32_t limb[5];
        memcpy(limb, ctx, 20);
        /* 5 x 26-bit */
        uint64_t acc0 = 0, acc1 = 0;
        int bit = 0;
        for (int i = 0; i < 5; i++) {
            uint64_t v = limb[i] & ((1u << 26) - 1);
            if (bit < 64) {
                acc0 |= v << bit;
                if (bit + 26 > 64)
                    acc1 |= v >> (64 - bit);
            } else {
                acc1 |= v << (bit - 64);
            }
            bit += 26;
        }
        /* 130 bits: bits 128-129 land in acc1's top... bit goes to 130, so acc1 holds bits 64..129 (66 bits). */
        h.l0 = acc0;
        h.l1 = acc1 & ~0ull; /* bits 64..127 */
        h.h2 = (acc1 >> 64) & 3ull; /* wait acc1 is only 64 bits. bits 128-129 are bits 64-65 of the second-and-beyond.
            bit positions:
            limb0: bits 0..25 -> acc0
            limb1: bits 26..51 -> acc0
            limb2: bits 52..77 -> acc0 (52..63) and acc1 (0..13)
            limb3: bits 78..103 -> acc1
            limb4: bits 104..129 -> acc1 (bits 104-127 -> acc1 bits 40..63) and bits 128-129 don't fit in acc1!
        */
        /* redo properly */
        unsigned __int128 wide = 0;
        bit = 0;
        for (int i = 0; i < 5; i++) {
            wide |= (unsigned __int128)(limb[i] & 0x3ffffffu) << bit;
            bit += 26;
        }
        h.l0 = (uint64_t)wide;
        h.l1 = (uint64_t)(wide >> 64);
        h.h2 = (uint64_t)(wide >> 128) & 3ull;
    } else {
        uint64_t q0, q1, q2;
        memcpy(&q0, ctx, 8);
        memcpy(&q1, ctx + 8, 8);
        memcpy(&q2, ctx + 16, 8);
        h.l0 = q0;
        h.l1 = q1;
        h.h2 = q2 & 3ull;
    }
    return h;
}

typedef struct {
    unsigned char *ct;
    const unsigned char *pt;
    size_t off, len;
    unsigned int counter0;
    unsigned int kw[8];
    unsigned int nw0, nw1, nw2;
    const unsigned char *prefix;
    size_t prefix_len;
    const unsigned char *tail;
    size_t tail_len;
    const unsigned char *polykey;
    u130 h;
    uint64_t blocks;
} job_t;

#define TILE (128 * 1024)

static void *job_worker(void *arg) {
    job_t *j = (job_t *)arg;
    unsigned int counter[4] = {j->counter0, j->nw0, j->nw1, j->nw2};
    unsigned int key[8];
    memcpy(key, j->kw, 32);

    unsigned char ctx[CTX_SIZE];
    Poly1305_Init(ctx, j->polykey);
    if (j->prefix_len)
        Poly1305_Update(ctx, j->prefix, j->prefix_len);

    size_t done = 0;
    while (done < j->len) {
        size_t tile = j->len - done;
        if (tile > TILE) tile = TILE;
        ChaCha20_ctr32(j->ct + j->off + done, j->pt + j->off + done, tile, key, counter);
        Poly1305_Update(ctx, j->ct + j->off + done, tile);
        /* advance counter by tile/64. tile is multiple of 64 except possibly the very end,
           and only the last job has a non-multiple, which is a single final tile. */
        counter[0] += (unsigned int)(tile >> 6);
        done += tile;
    }
    if (j->tail_len)
        Poly1305_Update(ctx, j->tail, j->tail_len);
    j->h = load_h(ctx);
    j->blocks = (j->prefix_len + j->len + j->tail_len) / 16;
    return NULL;
}

int chacha20_poly1305_encrypt(const unsigned char key[32],
                              const unsigned char nonce[12],
                              const unsigned char *pt, size_t n,
                              const unsigned char *aad, size_t aad_len,
                              unsigned char *ct, unsigned char tag[16],
                              int nt) {
    unsigned int kw[8];
    memcpy(kw, key, 32);
    unsigned int nw[3];
    memcpy(nw, nonce, 12);

    unsigned char zeros[64] = {0};
    unsigned char polykey[64];
    unsigned int c0[4] = {0, nw[0], nw[1], nw[2]};
    ChaCha20_ctr32(polykey, zeros, 64, kw, c0);

    if (nt < 1) nt = 1;
    if (nt > MAX_T) nt = MAX_T;
    if (n < 256 * 1024) nt = 1;
    if ((size_t)nt > n / 64) {
        nt = (int)(n / 64);
        if (nt < 1) nt = 1;
    }

    unsigned char prefix[48];
    size_t prefix_len = 0;
    if (aad_len) {
        size_t pad = (16 - (aad_len & 15)) & 15;
        /* aad is small (32 bytes in this task) but handle up to 32 + pad. If larger, heap. */
        prefix_len = aad_len + pad;
    }
    unsigned char *prefix_ptr = NULL;
    unsigned char prefix_stack[64];
    unsigned char *prefix_heap = NULL;
    if (prefix_len) {
        if (prefix_len <= sizeof(prefix_stack)) prefix_ptr = prefix_stack;
        else {
            prefix_heap = (unsigned char *)calloc(1, prefix_len);
            prefix_ptr = prefix_heap;
        }
        memset(prefix_ptr, 0, prefix_len);
        memcpy(prefix_ptr, aad, aad_len);
    }

    size_t ct_pad = (16 - (n & 15)) & 15;
    unsigned char tail[32];
    memset(tail, 0, sizeof(tail));
    size_t tail_len = ct_pad + 16;
    uint64_t al = (uint64_t)aad_len, cl = (uint64_t)n;
    memcpy(tail + ct_pad, &al, 8);
    memcpy(tail + ct_pad + 8, &cl, 8);

    job_t jobs[MAX_T];
    pthread_t ths[MAX_T];
    size_t base = (nt == 1) ? n : ((n / nt) & ~(size_t)63);
    size_t off = 0;
    int launched = 0;
    for (int i = 0; i < nt; i++) {
        size_t ln = (i == nt - 1) ? (n - off) : base;
        job_t *j = &jobs[i];
        j->ct = ct;
        j->pt = pt;
        j->off = off;
        j->len = ln;
        j->counter0 = 1u + (unsigned int)(off >> 6);
        memcpy(j->kw, kw, 32);
        j->nw0 = nw[0]; j->nw1 = nw[1]; j->nw2 = nw[2];
        j->polykey = polykey;
        j->prefix = (i == 0) ? prefix_ptr : NULL;
        j->prefix_len = (i == 0) ? prefix_len : 0;
        j->tail = (i == nt - 1) ? tail : NULL;
        j->tail_len = (i == nt - 1) ? tail_len : 0;
        j->blocks = 0;
        if (i < nt - 1) {
            pthread_create(&ths[i], NULL, job_worker, j);
            launched++;
        } else {
            job_worker(j);
        }
        off += ln;
    }
    for (int i = 0; i < launched; i++) pthread_join(ths[i], NULL);

    /* r from polykey */
    uint64_t r0, r1;
    memcpy(&r0, polykey, 8);
    memcpy(&r1, polykey + 8, 8);
    /* clamp */
    r0 &= 0x0ffffffc0fffffffull;
    r1 &= 0x0ffffffc0fffffffull;
    u130 r = u130_from_parts(r0, r1, 0);

    u130 h = jobs[0].h;
    for (int i = 1; i < nt; i++) {
        u130 factor = pow130(r, jobs[i].blocks ? 0 : 0); /* placeholder to keep compiler calm */
        (void)factor;
        h = mul130(h, pow130(r, jobs[i].blocks));
        h = add130(h, jobs[i].h);
    }
    /* Wait, that's wrong. h = h0 * r^{blocks1+blocks2+...} + h1 * r^{blocks2+...} + h_last
       The loop above does h = h0 * r^{blocks1} + h1, then * r^{blocks2} + h2, ...
       which equals h0 * r^{b1+b2+...} + h1 * r^{b2+...} + ... YES that's correct.
       But I wrote mul130(h, pow130(r, jobs[i].blocks)) which multiplies by r^{blocks of chunk i},
       and chunk i's blocks should be the exponent for the PREVIOUS accumulator. Yes: when adding
       chunk i, multiply accumulated by r^{blocks of chunk i}. Correct. */

    /* emit tag: write h into a fresh base-2^64 ctx and Poly1305_Final */
    unsigned char ctx[CTX_SIZE];
    Poly1305_Init(ctx, polykey);
    uint64_t q0 = h.l0, q1 = h.l1, q2 = h.h2;
    memcpy(ctx, &q0, 8);
    memcpy(ctx + 8, &q1, 8);
    memcpy(ctx + 16, &q2, 8);
    Poly1305_Final(ctx, tag);

    if (prefix_heap) free(prefix_heap);
    return 0;
}
