static double now() {
    struct timespec ts; clock_gettime(CLOCK_MONOTONIC, &ts);
    return ts.tv_sec + ts.tv_nsec * 1e-9;
}

typedef struct {
    unsigned char *dst, *src;
    size_t len;
    unsigned int counter0;
    int mode;
    volatile int flag; /* 0 wait, 1 run, 2 done, 3 exit */
    pthread_mutex_t mu;
    pthread_cond_t cv;
} W;

static void *worker(void *arg) {
    W *w = arg;
    unsigned int key[8] = {1,2,3,4,5,6,7,8};
    pthread_mutex_lock(&w->mu);
    for (;;) {
        while (w->flag == 0 || w->flag == 2)
            pthread_cond_wait(&w->cv, &w->mu);
        if (w->flag == 3) { pthread_mutex_unlock(&w->mu); return NULL; }
        int mode = w->mode;
        pthread_mutex_unlock(&w->mu);
        if (mode == 0) {
            memcpy(w->dst, w->src, w->len);
