            unsigned int counter[4] = {w->counter0, 1, 2, 3};
            ChaCha20_ctr32(w->dst, w->src, w->len, key, counter);
        }
        pthread_mutex_lock(&w->mu);
        w->flag = 2;
        pthread_cond_signal(&w->cv);
    }
}

