#include <stdint.h>
#include <stddef.h>
#include <string.h>
#include <stdlib.h>
#include <pthread.h>

void ChaCha20_ctr32(unsigned char *out, const unsigned char *inp,
                    size_t len, const unsigned int key[8],
                    const unsigned int counter[4]);
void Poly1305_Init(void *ctx, const unsigned char key[32]);
void Poly1305_Update(void *ctx, const unsigned char *inp, size_t len);
void Poly1305_Final(void *ctx, unsigned char mac[16]);

#define CTX_SIZE 248
#define MAX_T 6
#define TILE (256 * 1024)

typedef struct {
    uint64_t l0, l1;
    uint32_t h2; /* bits 128..129 */
} u130;

static u130 load_h(const unsigned char *ctx) {
    uint32_t flag = 0;
    memcpy(&flag, ctx + 0x14, 4);
    u130 h;
    if (flag) {
        uint32_t limb[5];
        memcpy(limb, ctx, 20);
        unsigned __int128 wide = 0;
        int bit = 0;
        for (int i = 0; i < 5; i++) {
            wide |= (unsigned __int128)(limb[i] & 0x3ffffffu) << bit;
            bit += 26;
        }
        h.l0 = (uint64_t)wide;
        h.l1 = (uint64_t)(wide >> 64);
        h.h2 = (uint32_t)((wide >> 128) & 3);
    } else {
        uint64_t q2;
        memcpy(&h.l0, ctx, 8);
        memcpy(&h.l1, ctx + 8, 8);
        memcpy(&q2, ctx + 16, 8);
        h.h2 = (uint32_t)(q2 & 3);
    }
    return h;
}

/* Reduce a value that may be a few times larger than 2^130 down to [0, 2^130). */
static void fold(uint64_t *r0, uint64_t *r1, uint64_t *r2) {
    while (*r2 >= 4) {
        uint64_t extra = (*r2 >> 2) * 5;
        *r2 &= 3ull;
        unsigned __int128 s = (unsigned __int128)(*r0) + extra;
        *r0 = (uint64_t)s;
        s = (unsigned __int128)(*r1) + (uint64_t)(s >> 64);
        *r1 = (uint64_t)s;
        *r2 += (uint64_t)(s >> 64);
    }
    if (*r2 == 3 && *r1 == ~0ull && *r0 >= (~4ull)) {
        unsigned __int128 s = (unsigned __int128)(*r0) + 5;
        *r0 = (uint64_t)s;
        s = (unsigned __int128)(*r1) + (uint64_t)(s >> 64);
        *r1 = (uint64_t)s;
        *r2 = 0;
    }
}

static u130 add130(u130 a, u130 b) {
    unsigned __int128 s = (unsigned __int128)a.l0 + b.l0;
    uint64_t r0 = (uint64_t)s;
    s = (unsigned __int128)a.l1 + b.l1 + (uint64_t)(s >> 64);
    uint64_t r1 = (uint64_t)s;
    uint64_t r2 = (uint64_t)a.h2 + b.h2 + (uint64_t)(s >> 64);
    fold(&r0, &r1, &r2);
    u130 o; o.l0 = r0; o.l1 = r1; o.h2 = (uint32_t)r2;
    return o;
}

static u130 mul130(u130 a, u130 b) {
    uint64_t a0 = a.l0, a1 = a.l1, a2 = a.h2;
    uint64_t b0 = b.l0, b1 = b.l1, b2 = b.h2;
    unsigned __int128 p;
    uint64_t w0, w1, w2, w3, w4, c;

    p = (unsigned __int128)a0 * b0;
    w0 = (uint64_t)p; w1 = (uint64_t)(p >> 64);
    p = (unsigned __int128)a0 * b1 + w1;
    w1 = (uint64_t)p; w2 = (uint64_t)(p >> 64);
    p = (unsigned __int128)a0 * b2 + w2;
    w2 = (uint64_t)p; w3 = (uint64_t)(p >> 64);
    w4 = 0;

    p = (unsigned __int128)a1 * b0 + w1;
    w1 = (uint64_t)p; c = (uint64_t)(p >> 64);
    p = (unsigned __int128)w2 + c; w2 = (uint64_t)p; c = (uint64_t)(p >> 64);
    p = (unsigned __int128)w3 + c; w3 = (uint64_t)p; w4 = (uint64_t)(p >> 64);

    p = (unsigned __int128)a1 * b1 + w2;
    w2 = (uint64_t)p; c = (uint64_t)(p >> 64);
    p = (unsigned __int128)w3 + c; w3 = (uint64_t)p; c = (uint64_t)(p >> 64);
    w4 += c;

    p = (unsigned __int128)a1 * b2 + w3;
    w3 = (uint64_t)p; w4 += (uint64_t)(p >> 64);

    p = (unsigned __int128)a2 * b0 + w2;
    w2 = (uint64_t)p; c = (uint64_t)(p >> 64);
    p = (unsigned __int128)w3 + c; w3 = (uint64_t)p; c = (uint64_t)(p >> 64);
    w4 += c;

    p = (unsigned __int128)a2 * b1 + w3;
    w3 = (uint64_t)p; w4 += (uint64_t)(p >> 64);

    w4 += a2 * b2;

    /* fold bits 130+ : high130 * 5 */
    uint64_t hi0 = (w2 >> 2) | (w3 << 62);
    uint64_t hi1 = (w3 >> 2) | (w4 << 62);
    uint64_t hi2 = w4 >> 2;

    uint64_t t0 = hi0 << 2;
    uint64_t t1 = (hi1 << 2) | (hi0 >> 62);
    uint64_t t2 = (hi2 << 2) | (hi1 >> 62);

    p = (unsigned __int128)t0 + hi0;
    uint64_t s0 = (uint64_t)p;
    p = (unsigned __int128)t1 + hi1 + (uint64_t)(p >> 64);
    uint64_t s1 = (uint64_t)p;
    p = (unsigned __int128)t2 + hi2 + (uint64_t)(p >> 64);
    uint64_t s2 = (uint64_t)p;

    uint64_t low2 = w2 & 3ull;
    p = (unsigned __int128)w0 + s0;
    uint64_t r0 = (uint64_t)p;
    p = (unsigned __int128)w1 + s1 + (uint64_t)(p >> 64);
    uint64_t r1 = (uint64_t)p;
    uint64_t r2 = low2 + s2 + (uint64_t)(p >> 64);
    fold(&r0, &r1, &r2);
    u130 o; o.l0 = r0; o.l1 = r1; o.h2 = (uint32_t)r2;
    return o;
}

static u130 pow130(u130 base, uint64_t exp) {
    u130 result; result.l0 = 1; result.l1 = 0; result.h2 = 0;
    while (exp) {
        if (exp & 1) result = mul130(result, base);
        exp >>= 1;
        if (exp) base = mul130(base, base);
    }
    return result;
}

typedef struct {
    pthread_t th;
    pthread_mutex_t mu;
    pthread_cond_t cv;
    volatile int cmd; /* 0 idle, 1 work, 2 exit */

    unsigned char *ct;
    const unsigned char *pt;
    size_t off, len;
    unsigned int counter0;
    unsigned int kw[8];
    unsigned int nw0, nw1, nw2;
    const unsigned char *prefix;
    size_t prefix_len;
    const unsigned char *tail;
    size_t tail_len;
    const unsigned char *polykey;
    u130 h;
    uint64_t blocks;
} worker_t;

static worker_t workers[MAX_T];
static int pool_ready = 0;
static pthread_mutex_t pool_mu = PTHREAD_MUTEX_INITIALIZER;

static void *worker_main(void *arg) {
    worker_t *w = arg;
    pthread_mutex_lock(&w->mu);
    for (;;) {
        while (w->cmd == 0)
            pthread_cond_wait(&w->cv, &w->mu);
        if (w->cmd == 2) {
            pthread_mutex_unlock(&w->mu);
            return NULL;
        }
        unsigned char *ct = w->ct;
        const unsigned char *pt = w->pt;
        size_t off = w->off, len = w->len;
        unsigned int counter0 = w->counter0;
        unsigned int kw[8];
        memcpy(kw, w->kw, 32);
        unsigned int nw0 = w->nw0, nw1 = w->nw1, nw2 = w->nw2;
        const unsigned char *prefix = w->prefix;
        size_t prefix_len = w->prefix_len;
        const unsigned char *tail = w->tail;
        size_t tail_len = w->tail_len;
        const unsigned char *polykey = w->polykey;
        pthread_mutex_unlock(&w->mu);

        unsigned int counter[4] = {counter0, nw0, nw1, nw2};
        unsigned char ctx[CTX_SIZE];
        Poly1305_Init(ctx, polykey);
        if (prefix_len)
            Poly1305_Update(ctx, prefix, prefix_len);
        size_t done = 0;
        while (done < len) {
            size_t tile = len - done;
            if (tile > TILE) tile = TILE;
            /* keep tiles 64-byte aligned except the final remainder of the whole message,
               which only the last worker sees and only as its final tile. */
            if (tile != (len - done) && (tile & 63))
                tile &= ~(size_t)63;
            ChaCha20_ctr32(ct + off + done, pt + off + done, tile, kw, counter);
            Poly1305_Update(ctx, ct + off + done, tile);
            counter[0] += (unsigned int)(tile >> 6);
            done += tile;
        }
        if (tail_len)
            Poly1305_Update(ctx, tail, tail_len);

        pthread_mutex_lock(&w->mu);
        w->h = load_h(ctx);
        w->blocks = (prefix_len + len + tail_len) / 16;
        w->cmd = 0;
        pthread_cond_signal(&w->cv);
    }
}

static void ensure_pool(void) {
    if (pool_ready) return;
    pthread_mutex_lock(&pool_mu);
    if (!pool_ready) {
        for (int i = 0; i < MAX_T; i++) {
            pthread_mutex_init(&workers[i].mu, NULL);
            pthread_cond_init(&workers[i].cv, NULL);
            workers[i].cmd = 0;
            pthread_create(&workers[i].th, NULL, worker_main, &workers[i]);
        }
        pool_ready = 1;
    }
    pthread_mutex_unlock(&pool_mu);
}

int chacha20_poly1305_encrypt(const unsigned char key[32],
                              const unsigned char nonce[12],
                              const unsigned char *pt, size_t n,
                              const unsigned char *aad, size_t aad_len,
                              unsigned char *ct, unsigned char tag[16],
                              int nt) {
    ensure_pool();

    unsigned int kw[8];
    memcpy(kw, key, 32);
    unsigned int nw[3];
    memcpy(nw, nonce, 12);

    unsigned char zeros[64] = {0};
    unsigned char polykey[64];
    unsigned int c0[4] = {0, nw[0], nw[1], nw[2]};
    ChaCha20_ctr32(polykey, zeros, 64, kw, c0);

    if (nt < 1) nt = 1;
    if (nt > MAX_T) nt = MAX_T;
    if (n < 128 * 1024) nt = 1;
    if ((size_t)nt > n / 64) {
        nt = (int)(n / 64);
        if (nt < 1) nt = 1;
    }

    unsigned char prefix_buf[64];
    size_t prefix_len = 0;
    if (aad_len) {
        size_t pad = (16 - (aad_len & 15)) & 15;
        prefix_len = aad_len + pad;
        if (prefix_len > sizeof(prefix_buf)) prefix_len = sizeof(prefix_buf); /* aad is 32 in this task */
        memset(prefix_buf, 0, prefix_len);
        memcpy(prefix_buf, aad, aad_len < prefix_len ? aad_len : prefix_len);
    }

    size_t ct_pad = (16 - (n & 15)) & 15;
    unsigned char tail[32];
    memset(tail, 0, sizeof(tail));
    size_t tail_len = ct_pad + 16;
    uint64_t al = (uint64_t)aad_len, clen = (uint64_t)n;
    memcpy(tail + ct_pad, &al, 8);
    memcpy(tail + ct_pad + 8, &clen, 8);

    size_t base = (nt == 1) ? n : ((n / nt) & ~(size_t)63);
    size_t off = 0;
    for (int i = 0; i < nt; i++) {
        size_t ln = (i == nt - 1) ? (n - off) : base;
        worker_t *w = &workers[i];
        pthread_mutex_lock(&w->mu);
        w->ct = ct;
        w->pt = pt;
        w->off = off;
        w->len = ln;
        w->counter0 = 1u + (unsigned int)(off >> 6);
        memcpy(w->kw, kw, 32);
        w->nw0 = nw[0]; w->nw1 = nw[1]; w->nw2 = nw[2];
        w->polykey = polykey;
        w->prefix = (i == 0 && prefix_len) ? prefix_buf : NULL;
        w->prefix_len = (i == 0) ? prefix_len : 0;
        w->tail = (i == nt - 1) ? tail : NULL;
        w->tail_len = (i == nt - 1) ? tail_len : 0;
        w->cmd = 1;
        pthread_cond_signal(&w->cv);
        pthread_mutex_unlock(&w->mu);
        off += ln;
    }
    u130 hs[MAX_T];
    uint64_t blocks[MAX_T];
    for (int i = 0; i < nt; i++) {
        worker_t *w = &workers[i];
        pthread_mutex_lock(&w->mu);
        while (w->cmd != 0)
            pthread_cond_wait(&w->cv, &w->mu);
        hs[i] = w->h;
        blocks[i] = w->blocks;
        pthread_mutex_unlock(&w->mu);
    }

    uint64_t r0, r1;
    memcpy(&r0, polykey, 8);
    memcpy(&r1, polykey + 8, 8);
    r0 &= 0x0ffffffc0fffffffull;
    r1 &= 0x0ffffffc0fffffffull;
    u130 r; r.l0 = r0; r.l1 = r1; r.h2 = 0;

    u130 h = hs[0];
    for (int i = 1; i < nt; i++) {
        h = mul130(h, pow130(r, blocks[i]));
        h = add130(h, hs[i]);
    }

    unsigned char ctx[CTX_SIZE];
    Poly1305_Init(ctx, polykey);
    uint64_t q0 = h.l0, q1 = h.l1, q2 = h.h2;
    memcpy(ctx, &q0, 8);
    memcpy(ctx + 8, &q1, 8);
    memcpy(ctx + 16, &q2, 8);
    Poly1305_Final(ctx, tag);
    return 0;
}
