#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <pthread.h>
#include <stdint.h>

void ChaCha20_ctr32(unsigned char *out, const unsigned char *inp,
                    size_t len, const unsigned int key[8],
                    const unsigned int counter[4]);
void Poly1305_Init(void *ctx, const unsigned char key[32]);
void Poly1305_Update(void *ctx, const unsigned char *inp, size_t len);
void Poly1305_Final(void *ctx, unsigned char mac[16]);

static double now() { struct timespec ts; clock_gettime(CLOCK_MONOTONIC,&ts); return ts.tv_sec + ts.tv_nsec*1e-9; }

typedef struct { unsigned char *ct,*pt; size_t off,len; unsigned int ctr; unsigned int key[8]; unsigned char pkey[32]; } J;

static void *work(void *arg) {
    J *j = arg;
    unsigned int counter[4] = {j->ctr, 1, 2, 3};
    unsigned char ctx[248];
    ChaCha20_ctr32(j->ct + j->off, j->pt + j->off, j->len, j->key, counter);
    Poly1305_Init(ctx, j->pkey);
    Poly1305_Update(ctx, j->ct + j->off, j->len);
    return NULL;
}

int main() {
    size_t n = 40ULL*1024*1024;
    unsigned char *pt = aligned_alloc(64, n);
    unsigned char *ct = aligned_alloc(64, n);
    memset(pt, 1, n);
    int nts[] = {1,2,4,6};
    for (int ti = 0; ti < 4; ti++) {
        int nt = nts[ti];
        size_t base = (n / nt) & ~63ULL;
        J jobs[8]; pthread_t th[8];
        /* warmup */
        for (int i = 0; i < nt; i++) {
            size_t off = i * base;
            size_t ln = (i == nt-1) ? n - off : base;
            jobs[i].ct = ct; jobs[i].pt = pt; jobs[i].off = off; jobs[i].len = ln;
            jobs[i].ctr = 1 + (unsigned int)(off>>6);
            memset(jobs[i].key, 3, 32); memset(jobs[i].pkey, 5, 32);
        }
        for (int i = 0; i < nt-1; i++) pthread_create(&th[i], NULL, work, &jobs[i]);
        work(&jobs[nt-1]);
        for (int i = 0; i < nt-1; i++) pthread_join(th[i], NULL);

        int reps = 4;
        double t0 = now();
        for (int r = 0; r < reps; r++) {
            for (int i = 0; i < nt-1; i++) pthread_create(&th[i], NULL, work, &jobs[i]);
            work(&jobs[nt-1]);
            for (int i = 0; i < nt-1; i++) pthread_join(th[i], NULL);
        }
        double dt = now() - t0;
        printf("nt=%d fresh: %.2f ms  %.2f GB/s\n", nt, dt/reps*1e3, reps*(double)n/dt/1e9);
    }
    printf("ct0=%02x\n", ct[0]);
    return 0;
}
