#define _DARWIN_C_SOURCE
#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <pthread.h>
#include <stdint.h>
#include <mach/thread_act.h>
#include <mach/thread_policy.h>

void ChaCha20_ctr32(unsigned char *out, const unsigned char *inp,
                    size_t len, const unsigned int key[8],
                    const unsigned int counter[4]);
void Poly1305_Init(void *ctx, const unsigned char key[32]);
void Poly1305_Update(void *ctx, const unsigned char *inp, size_t len);

static double now() { struct timespec ts; clock_gettime(CLOCK_MONOTONIC,&ts); return ts.tv_sec + ts.tv_nsec*1e-9; }

typedef struct {
    unsigned char *ct, *pt;
    size_t off, len, stride;
    unsigned int ctr;
    unsigned int key[8];
    unsigned char pkey[32];
    int mode; /* 0 contiguous, 1 strided tiles */
    volatile int flag; /* 0 wait, 1 run, 2 done */
} W;

static void do_work(W *w) {
    unsigned int counter[4] = {w->ctr, 1, 2, 3};
    unsigned int key[8]; memcpy(key, w->key, 32);
    unsigned char ctx[248];
    Poly1305_Init(ctx, w->pkey);
    if (w->mode == 0) {
        ChaCha20_ctr32(w->ct + w->off, w->pt + w->off, w->len, key, counter);
        Poly1305_Update(ctx, w->ct + w->off, w->len);
    } else {
        size_t tile = 64 * 1024;
        size_t pos = w->off;
        size_t end = w->off + w->len;
        while (pos < end) {
            size_t ln = tile;
            if (pos + ln > end) ln = end - pos;
            unsigned int c[4] = {(unsigned int)(1 + (pos >> 6)), 1, 2, 3};
            ChaCha20_ctr32(w->ct + pos, w->pt + pos, ln, key, c);
            Poly1305_Update(ctx, w->ct + pos, ln);
            pos += w->stride;
            /* this naive version only does one region; real interleave handled by caller via multiple ranges.
               Here mode 1 means the worker owns every stride-th tile starting at off. */
        }
    }
}

static void *main_w(void *arg) {
    W *w = arg;
    for (;;) {
        while (w->flag == 0 || w->flag == 2) ;
        if (w->flag == 3) return NULL;
        do_work(w);
        w->flag = 2;
    }
}

/* interleaved: worker i processes tiles i, i+nt, ... but Poly1305 must be in order, so each worker
   keeps its own state over its own (noncontiguous) bytes — that's fine for our combine approach
   ONLY if each worker's bytes are a contiguous range. Interleaving breaks the single-accumulator
   combine unless each tile is its own hash. Skip interleave; just pin and use contiguous. */

static void pin(pthread_t th, int core) {
    thread_affinity_policy_data_t pol;
    pol.affinity_tag = core + 1;
    thread_policy_set(pthread_mach_thread_np(th), THREAD_AFFINITY_POLICY,
                      (thread_policy_t)&pol, THREAD_AFFINITY_POLICY_COUNT);
}

int main() {
    size_t n = 40ULL*1024*1024;
    unsigned char *pt = aligned_alloc(64, n);
    unsigned char *ct = aligned_alloc(64, n);
    memset(pt, 1, n);
    for (int nt = 1; nt <= 6; nt++) {
        size_t base = (n / nt) & ~63ULL;
        W ws[8]; pthread_t th[8];
        for (int i = 0; i < nt; i++) {
            size_t off = (size_t)i * base;
            ws[i].ct = ct; ws[i].pt = pt; ws[i].off = off;
            ws[i].len = (i == nt-1) ? n - off : base;
            ws[i].ctr = 1 + (unsigned int)(off >> 6);
            memset(ws[i].key, 3, 32); memset(ws[i].pkey, 5, 32);
            ws[i].mode = 0; ws[i].flag = 0;
            pthread_create(&th[i], NULL, main_w, &ws[i]);
            pin(th[i], i);
        }
        /* warmup */
        for (int i = 0; i < nt; i++) ws[i].flag = 1;
        for (int i = 0; i < nt; i++) { while (ws[i].flag != 2) ; ws[i].flag = 0; }
        int reps = 4;
        double t0 = now();
        for (int r = 0; r < reps; r++) {
            for (int i = 0; i < nt; i++) ws[i].flag = 1;
            for (int i = 0; i < nt; i++) { while (ws[i].flag != 2) ; ws[i].flag = 0; }
        }
        double dt = now() - t0;
        printf("nt=%d pinned: %.2f ms  %.2f GB/s\n", nt, dt/reps*1e3, reps*(double)n/dt/1e9);
        for (int i = 0; i < nt; i++) ws[i].flag = 3;
        for (int i = 0; i < nt; i++) pthread_join(th[i], NULL);
    }
    printf("ct0=%02x\n", ct[0]);
    return 0;
}
EOF
