#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <pthread.h>
#include <stdint.h>
#include <sched.h>
#include <mach/thread_act.h>
#include <mach/thread_policy.h>

void ChaCha20_ctr32(unsigned char *out, const unsigned char *inp,
                    size_t len, const unsigned int key[8],
                    const unsigned int counter[4]);
void Poly1305_Init(void *ctx, const unsigned char key[32]);
void Poly1305_Update(void *ctx, const unsigned char *inp, size_t len);

static double now() { struct timespec ts; clock_gettime(CLOCK_MONOTONIC,&ts); return ts.tv_sec + ts.tv_nsec*1e-9; }

typedef struct {
    unsigned char *ct, *pt;
    size_t off, len;
    unsigned int ctr;
    unsigned int key[8];
    unsigned char pkey[32];
    int cmd; /* 0 idle, 1 run, 2 exit */
    pthread_mutex_t mu;
    pthread_cond_t cv;
} W;

static void *main_w(void *arg) {
    W *w = arg;
    pthread_mutex_lock(&w->mu);
    for (;;) {
        while (w->cmd == 0) pthread_cond_wait(&w->cv, &w->mu);
        if (w->cmd == 2) { pthread_mutex_unlock(&w->mu); return NULL; }
        unsigned char *ct = w->ct, *pt = w->pt;
        size_t off = w->off, len = w->len;
        unsigned int ctr = w->ctr;
        unsigned int key[8]; memcpy(key, w->key, 32);
        unsigned char pkey[32]; memcpy(pkey, w->pkey, 32);
        pthread_mutex_unlock(&w->mu);

        unsigned int counter[4] = {ctr, 1, 2, 3};
        unsigned char ctx[248];
        ChaCha20_ctr32(ct + off, pt + off, len, key, counter);
        Poly1305_Init(ctx, pkey);
        Poly1305_Update(ctx, ct + off, len);

        pthread_mutex_lock(&w->mu);
        w->cmd = 0;
        pthread_cond_signal(&w->cv);
    }
}

static void pin(pthread_t th, int core) {
    thread_affinity_policy_data_t pol;
    pol.affinity_tag = core + 1;
    thread_policy_set(pthread_mach_thread_np(th), THREAD_AFFINITY_POLICY,
                      (thread_policy_t)&pol, THREAD_AFFINITY_POLICY_COUNT);
}

static void dispatch(W *ws, int nt) {
    for (int i = 0; i < nt; i++) {
        pthread_mutex_lock(&ws[i].mu);
        ws[i].cmd = 1;
        pthread_cond_signal(&ws[i].cv);
        pthread_mutex_unlock(&ws[i].mu);
    }
    for (int i = 0; i < nt; i++) {
        pthread_mutex_lock(&ws[i].mu);
        while (ws[i].cmd != 0) pthread_cond_wait(&ws[i].cv, &ws[i].mu);
        pthread_mutex_unlock(&ws[i].mu);
    }
}

int main() {
    size_t n = 40ULL*1024*1024;
    unsigned char *pt = aligned_alloc(64, n);
    unsigned char *ct = aligned_alloc(64, n);
    memset(pt, 1, n);
    for (int nt = 1; nt <= 6; nt++) {
        size_t base = (n / nt) & ~63ULL;
        W ws[8]; pthread_t th[8];
        for (int i = 0; i < nt; i++) {
            size_t off = (size_t)i * base;
            ws[i].ct = ct; ws[i].pt = pt; ws[i].off = off;
            ws[i].len = (i == nt-1) ? n - off : base;
            ws[i].ctr = 1 + (unsigned int)(off >> 6);
            memset(ws[i].key, 3, 32); memset(ws[i].pkey, 5, 32);
            ws[i].cmd = 0;
            pthread_mutex_init(&ws[i].mu, NULL);
            pthread_cond_init(&ws[i].cv, NULL);
            pthread_create(&th[i], NULL, main_w, &ws[i]);
            pin(th[i], i);
        }
        dispatch(ws, nt); /* warmup */
        int reps = 4;
        double t0 = now();
        for (int r = 0; r < reps; r++) dispatch(ws, nt);
        double dt = now() - t0;
        printf("nt=%d pinned pool: %.2f ms  %.2f GB/s\n", nt, dt/reps*1e3, reps*(double)n/dt/1e9);
        for (int i = 0; i < nt; i++) {
            pthread_mutex_lock(&ws[i].mu);
            ws[i].cmd = 2; pthread_cond_signal(&ws[i].cv);
            pthread_mutex_unlock(&ws[i].mu);
        }
        for (int i = 0; i < nt; i++) pthread_join(th[i], NULL);
    }
    printf("ct0=%02x\n", ct[0]);
    return 0;
}
