#include <stdio.h>
#include <stdint.h>
#include <string.h>

typedef struct { uint64_t l0, l1; uint32_t h2; } u130;

static void fold(uint64_t *r0, uint64_t *r1, uint64_t *r2) {
    while (*r2 >= 4) {
        uint64_t extra = (*r2 >> 2) * 5;
        *r2 &= 3ull;
        unsigned __int128 s = (unsigned __int128)(*r0) + extra;
        *r0 = (uint64_t)s;
        s = (unsigned __int128)(*r1) + (uint64_t)(s >> 64);
        *r1 = (uint64_t)s;
        *r2 += (uint64_t)(s >> 64);
    }
    if (*r2 == 3 && *r1 == ~0ull && *r0 >= (~4ull)) {
        unsigned __int128 s = (unsigned __int128)(*r0) + 5;
        *r0 = (uint64_t)s;
        s = (unsigned __int128)(*r1) + (uint64_t)(s >> 64);
        *r1 = (uint64_t)s;
        *r2 = 0;
    }
}

static u130 mul130(u130 a, u130 b) {
    uint64_t a0 = a.l0, a1 = a.l1, a2 = a.h2;
    uint64_t b0 = b.l0, b1 = b.l1, b2 = b.h2;
    unsigned __int128 p;
    uint64_t w0, w1, w2, w3, w4, c;
    p = (unsigned __int128)a0 * b0;
    w0 = (uint64_t)p; w1 = (uint64_t)(p >> 64);
    p = (unsigned __int128)a0 * b1 + w1;
    w1 = (uint64_t)p; w2 = (uint64_t)(p >> 64);
    p = (unsigned __int128)a0 * b2 + w2;
    w2 = (uint64_t)p; w3 = (uint64_t)(p >> 64);
    w4 = 0;
    p = (unsigned __int128)a1 * b0 + w1;
    w1 = (uint64_t)p; c = (uint64_t)(p >> 64);
    p = (unsigned __int128)w2 + c; w2 = (uint64_t)p; c = (uint64_t)(p >> 64);
    p = (unsigned __int128)w3 + c; w3 = (uint64_t)p; w4 = (uint64_t)(p >> 64);
    p = (unsigned __int128)a1 * b1 + w2;
    w2 = (uint64_t)p; c = (uint64_t)(p >> 64);
    p = (unsigned __int128)w3 + c; w3 = (uint64_t)p; c = (uint64_t)(p >> 64);
    w4 += c;
    p = (unsigned __int128)a1 * b2 + w3;
    w3 = (uint64_t)p; w4 += (uint64_t)(p >> 64);
    p = (unsigned __int128)a2 * b0 + w2;
    w2 = (uint64_t)p; c = (uint64_t)(p >> 64);
    p = (unsigned __int128)w3 + c; w3 = (uint64_t)p; c = (uint64_t)(p >> 64);
    w4 += c;
    p = (unsigned __int128)a2 * b1 + w3;
    w3 = (uint64_t)p; w4 += (uint64_t)(p >> 64);
    w4 += a2 * b2;
    uint64_t hi0 = (w2 >> 2) | (w3 << 62);
    uint64_t hi1 = (w3 >> 2) | (w4 << 62);
    uint64_t hi2 = w4 >> 2;
    uint64_t t0 = hi0 << 2;
    uint64_t t1 = (hi1 << 2) | (hi0 >> 62);
    uint64_t t2 = (hi2 << 2) | (hi1 >> 62);
    p = (unsigned __int128)t0 + hi0; uint64_t s0 = (uint64_t)p;
    p = (unsigned __int128)t1 + hi1 + (uint64_t)(p >> 64); uint64_t s1 = (uint64_t)p;
    p = (unsigned __int128)t2 + hi2 + (uint64_t)(p >> 64); uint64_t s2 = (uint64_t)p;
    uint64_t low2 = w2 & 3ull;
    p = (unsigned __int128)w0 + s0; uint64_t r0 = (uint64_t)p;
    p = (unsigned __int128)w1 + s1 + (uint64_t)(p >> 64); uint64_t r1 = (uint64_t)p;
    uint64_t r2 = low2 + s2 + (uint64_t)(p >> 64);
    fold(&r0, &r1, &r2);
    u130 o; o.l0 = r0; o.l1 = r1; o.h2 = (uint32_t)r2;
    return o;
}

static u130 pow130(u130 base, uint64_t exp) {
    u130 result; result.l0 = 1; result.l1 = 0; result.h2 = 0;
    while (exp) {
        if (exp & 1) result = mul130(result, base);
        exp >>= 1;
        if (exp) base = mul130(base, base);
    }
    return result;
}

int main() {
    /* r = a known value, compare r^2 and r^83328 against python */
    u130 r;
    r.l0 = 0x0ffffffc0fffffffULL;
    r.l1 = 0x0ffffffc0fffffffULL;
    r.h2 = 0;
    u130 r2 = mul130(r, r);
    printf("r^2 %016llx %016llx %u\n", (unsigned long long)r2.l0, (unsigned long long)r2.l1, r2.h2);
    u130 rp = pow130(r, 83328);
    printf("r^83328 %016llx %016llx %u\n", (unsigned long long)rp.l0, (unsigned long long)rp.l1, rp.h2);
    return 0;
}
